+export function InviteDialog({ workspaceId, onClose }: Props) {
+  const { invite, pending, error } = useInvitations(workspaceId);
+  const [email, setEmail] = useState("");
+  return (
+    <dialog open aria-labelledby="invite-title">
+      <h2 id="invite-title">Invite a teammate</h2>
+      <input value={email} onChange={(e) => setEmail(e.target.value)} type="email" />
+      <Button disabled={pending} onClick={() => invite(email, "member").then(onClose)}>Send invite</Button>
+      {error && <p role="alert">{error.message}</p>}
+    </dialog>
+  );
+}

